class Solution {
  public int findMaximumLength(int[] nums) {
    int n = nums.length;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
    int[] best = new int[n + 1]; // most segments for the first i elements
    long[] lastSum = new long[n + 1]; // smallest possible last segment sum for that count
    int[] queue = new int[n + 2];
    int head = 0, tail = 0;
    queue[tail++] = 0;
    for (int i = 1; i <= n; i++) {
      // drop candidates that are dominated: the next one already fits under prefix[i]
      while (tail - head >= 2 && prefix[queue[head + 1]] + lastSum[queue[head + 1]] <= prefix[i])
        head++;
      int j = queue[head];
      best[i] = best[j] + 1;
      lastSum[i] = prefix[i] - prefix[j];
      while (tail > head
          && prefix[queue[tail - 1]] + lastSum[queue[tail - 1]] >= prefix[i] + lastSum[i]) tail--;
      queue[tail++] = i;
    }
    return best[n];
  }
}
